head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//
scwin.vScrenID = 'ULDMGT30301.gfm';
///////// 1. 변수 및 선언 영역 /////////
scwin.g_ACPT_NO = '';
scwin.isRun = true;
scwin.isAuto = true;
scwin.threadID;

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅  
    scwin.setContnId(row);
    if (colid === 'DISCLS_TRNSM_TITLE') {

        //----W-Craft WebSquare 변환 확인: fn_OpenDisclViewer_MGT----//
        fn_OpenDisclViewer_MGT(scwin.g_ACPT_NO, scwin.vScrenID);
    }
};

scwin.btn_cal_onclick = function(e) {

    //----W-Craft WebSquare 변환 확인: popUpCalendar----//
    popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); //alert('image_2.onclick');

};

scwin.btn_Search_onclick = function(e) {
    if (txb_date.getValue() !== "") {
        scwin.stopReload();
        scwin.isAuto = false;
        scwin.reloadAuto(); //alert();

    } else {
        alert("일자를 지정하십시요");
    }
};

scwin.button_1_onclick = function(e) {
    scwin.stopReload();
};

scwin.btn_Excel_onclick = function(e) {

    //----W-Craft WebSquare 변환 확인: GridToExcel----//
    grd_Grid.GridToExcel("Koscom 공시 전송현황", "", "8");
};

scwin.MxDataSetErrCnt_OnLoadCompleted = function(rowcount) {

    //----W-Craft WebSquare 변환 확인: NameValue----//
    if (rowcount !== 0) txtErrCnt.setValue("불일치 건수  총 " + MxDataSetErrCnt.NameValue(1, "CNT") + " 건");
};

scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    textbox_1.setValue("총 " + rowcount + "건");
};

///////// 5. 일반/업무 함수 영역 /////////
 //true:자동refres, true:날짜 변경등으로 인한 수동 조회.			
scwin.code1Sync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.listSync = async function() {

    //----W-Craft WebSquare 변환 확인: ValueOfIndex----//
    let type = MxCombo_1.ValueOfIndex("Column2", MxCombo_1.Index);
    if (type === 'A') type = '';

    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/koscomtrnslog.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_MxDataSetErrCnt",
        action : "/koscomtrnslog.do",
        ref : "",
        target : "MxDataSetErrCnt=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.setContnId = function(obj) {

    //----W-Craft WebSquare 변환 확인: NameString----//
    scwin.g_ACPT_NO = MxDataSet.NameString(eval(obj), "ACPT_NO");
};

scwin.reloadAuto = function() {

    //----W-Craft WebSquare 변환 확인: setInterval----//
    scwin.threadID = setInterval('fn_list_sync()', 60000); //60초
    scwin.isRun = true;
    scwin.setAlertTxt();
    scwin.listSync();
};

scwin.setAlertTxt = function() {
    if (scwin.isRun) txtAlert.setValue("1분 마다 reload 되고 있습니다.");

    else txtAlert.setValue("reload 중지되었습니다.");
};

scwin.stopReload = function() {

    //----W-Craft WebSquare 변환 확인: clearInterval----//
    clearInterval(scwin.threadID);
    scwin.isRun = false;
    scwin.setAlertTxt();
};

scwin.gform_onload = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_MxDataSetErrCnt",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSetErrCnt=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.code1Sync();
    $c.libRoundPanel.PanelToGroupBox_01(panel_1);
    //PanelToGroupBox_02(panel_2);

    //----W-Craft WebSquare 변환 확인: toDaySet----//
    toDaySet(txb_date);
    scwin.reloadAuto();
};
